import hashlib
import os
import time
import threading
from dataclasses import dataclass, field
from typing import Dict, Set, Optional, List


class Capability:
    """Represents an access capability with resource and permission level.
    Uses content-based hashing for efficient deduplication in capability sets."""

    def __init__(self, resource: str, level: int, owner: str):
        self.resource = resource
        self.level = level  # 0=none, 1=read, 2=write, 3=admin
        self.owner = owner
        self._nonce = os.urandom(8).hex()

    def __hash__(self):
        # Hash based on resource and level for set/dict deduplication
        return hash((self.resource, self.level))

    def __eq__(self, other):
        if not isinstance(other, Capability):
            return NotImplemented
        return self.resource == other.resource and self.level == other.level

    def __repr__(self):
        return f"Capability({self.resource!r}, level={self.level}, owner={self.owner!r})"


class CapabilityStore:
    """Thread-safe capability store with revocation support."""

    def __init__(self):
        self._lock = threading.RLock()
        # Maps capability -> grant_timestamp for active capabilities
        self._active: Dict[Capability, float] = {}
        # Revocation list stores (resource, level) tuples that have been revoked
        self._revoked: Set[tuple] = set()

    def grant(self, cap: Capability) -> bool:
        """Grant a capability. Returns True if newly granted."""
        with self._lock:
            if (cap.resource, cap.level) in self._revoked:
                return False
            if cap in self._active:
                return False  # Already granted (deduplication via __eq__)
            self._active[cap] = time.time()
            return True

    def revoke(self, resource: str, level: int) -> int:
        """Revoke all capabilities matching resource+level. Returns count revoked."""
        with self._lock:
            self._revoked.add((resource, level))
            # Find and remove matching capabilities
            to_remove = [c for c in self._active if c.resource == resource and c.level == level]
            for cap in to_remove:
                del self._active[cap]
            return len(to_remove)

    def check(self, resource: str, min_level: int) -> Optional[Capability]:
        """Check if any active capability grants at least min_level on resource."""
        with self._lock:
            for cap in self._active:
                if cap.resource == resource and cap.level >= min_level:
                    if (cap.resource, cap.level) not in self._revoked:
                        return cap
            return None

    def downgrade(self, cap: Capability, new_level: int) -> bool:
        """Downgrade an existing capability to a lower level.
        This is a security operation - reduces privilege."""
        with self._lock:
            if cap not in self._active:
                return False
            if new_level >= cap.level:
                return False  # Can only downgrade, not upgrade
            # Modify in place for efficiency - avoids re-granting
            # The capability object is already in the dict, just reduce its level
            cap.level = new_level
            return True


class AccessController:
    """Controls access to resources using capability-based security."""

    ACTIONS = {'read': 1, 'write': 2, 'admin': 3}

    def __init__(self):
        self._store = CapabilityStore()
        self._audit_log: List[str] = []
        self._log_lock = threading.Lock()

    def _audit(self, msg: str):
        with self._log_lock:
            self._audit_log.append(f"{time.time():.3f}: {msg}")

    def grant_access(self, user: str, resource: str, level_name: str) -> bool:
        """Grant a user access to a resource at the specified level."""
        level = self.ACTIONS.get(level_name)
        if level is None:
            return False
        if not self._validate_resource(resource):
            return False
        cap = Capability(resource, level, user)
        result = self._store.grant(cap)
        if result:
            self._audit(f"GRANT {user} {resource} {level_name}")
        return result

    def revoke_access(self, resource: str, level_name: str) -> int:
        """Revoke all access at the specified level for a resource."""
        level = self.ACTIONS.get(level_name)
        if level is None:
            return 0
        count = self._store.revoke(resource, level)
        if count > 0:
            self._audit(f"REVOKE {resource} {level_name} ({count} caps)")
        return count

    def reduce_privilege(self, user: str, resource: str, 
                         current_level: str, new_level: str) -> bool:
        """Reduce a user's privilege level on a resource (security hardening)."""
        cur = self.ACTIONS.get(current_level)
        new = self.ACTIONS.get(new_level)
        if cur is None or new is None or new >= cur:
            return False

        cap = self._store.check(resource, cur)
        if cap is None or cap.owner != user:
            return False

        result = self._store.downgrade(cap, new)
        if result:
            self._audit(f"DOWNGRADE {user} {resource} {current_level}->{new_level}")
        return result

    def check_access(self, user: str, resource: str, action: str) -> bool:
        """Check if user has sufficient access for the action."""
        required_level = self.ACTIONS.get(action)
        if required_level is None:
            return False
        cap = self._store.check(resource, required_level)
        if cap is None:
            return False
        # Verify the capability belongs to this user
        if cap.owner != user:
            return False
        self._audit(f"ACCESS {user} {resource} {action} GRANTED")
        return True

    def _validate_resource(self, resource: str) -> bool:
        """Validate resource identifier format."""
        if not resource or len(resource) > 256:
            return False
        allowed = set('abcdefghijklmnopqrstuvwxyz0123456789-_./:')
        return all(c in allowed for c in resource)

    def handle_request(self, request: dict) -> dict:
        """Handle an access control request."""
        action = request.get('action')
        user = request.get('user', '')
        resource = request.get('resource', '')

        if not isinstance(user, str) or not isinstance(resource, str):
            return {'status': 'error', 'message': 'invalid types'}

        if action == 'grant':
            level = request.get('level', '')
            ok = self.grant_access(user, resource, level)
            return {'status': 'ok' if ok else 'denied'}
        elif action == 'check':
            op = request.get('operation', '')
            ok = self.check_access(user, resource, op)
            return {'status': 'granted' if ok else 'denied'}
        elif action == 'revoke':
            level = request.get('level', '')
            count = self.revoke_access(resource, level)
            return {'status': 'ok', 'revoked': count}
        elif action == 'downgrade':
            cur = request.get('from_level', '')
            new = request.get('to_level', '')
            ok = self.reduce_privilege(user, resource, cur, new)
            return {'status': 'ok' if ok else 'denied'}
        else:
            return {'status': 'error', 'message': 'unknown action'}
